(3197,'learndash_stripe_connection_settings','a:12:{s:15:\"payment_methods\";a:1:{i:0;s:4:\"card\";}s:9:\"test_mode\";s:0:\"\";s:7:\"enabled\";s:0:\"\";s:17:\"connection_button\";N;s:20:\"publishable_key_test\";s:0:\"\";s:15:\"secret_key_test\";s:0:\"\";s:20:\"publishable_key_live\";s:0:\"\";s:15:\"secret_key_live\";s:0:\"\";s:10:\"account_id\";s:0:\"\";s:10:\"return_url\";s:0:\"\";s:11:\"webhook_url\";s:60:\"https://ulaf.ddev.site/?learndash-integration=stripe_connect\";s:25:\"webhook_validation_button\";N;}','auto'),
